const LESSONS = [L1, L2, L3, L4, L5, L6, L7, L8, L9, L10]
// ─── Дополнения по аудиту полноты: серии кадров, текстовые эквиваленты, разборы ──────────
type Par = ReturnType<typeof p>
const LK = (k: string): AccLesson => (LESSONS as AccLesson[]).find(l => l.key === k) as AccLesson
const ins = (k: string, after: string, ...ps: Par[]) => {
  const arr = LK(k).content.paragraphs
  const i = arr.findIndex(x => x.id === after)
  if (i < 0) throw new Error(`ins: нет абзаца ${after} в ${k}`)
  arr.splice(i + 1, 0, ...ps)
}
const addFigs = (k: string, f: Array<{ after: string; caption: string; src: string }>) => {
  const F = FIGS as unknown as Record<string, unknown[]>
  F[k] = [...(F[k] ?? []), ...f]
}
const cap = (n: number, m: number, t: string) => `Учебная реконструкция: шаг ${n} из ${m} — ${t}.`
const XLA = 'Excel для Windows (Microsoft 365)'
/** Лист Excel с произвольными буквами столбцов и номерами строк. */
const grid = (cols: string[], rows: string[][], first = 1, hi?: [number, number]) => ({ headers: ['', ...cols], rows: rows.map((r, i) => [String(first + i), ...r]), hi })

// m04-01: смешанные ссылки на примере, Mac
ins('m04-01', 'abs', p('mix1', '**Смешанные ссылки на примере (нужны в уроках о нескольких условиях и в HARD).** На пустом листе введите в A2:A4 числа 1, 2, 3, а в B1:D1 числа 10, 20, 30. В B2 введите `=$A2*B$1` и протяните на B2:D4. Столбец A закреплён (`$A`), строка 1 закреплена (`B$1`): формула в C3 станет `=$A3*C$1`. Результат: строка 2 — 10, 20, 30; строка 3 — 20, 40, 60; строка 4 — 30, 60, 90. С `$A$2*B1` или `A2*B1` таблица бы «поехала». **Mac:** переключатель типа ссылки — `Cmd+T` (по справке Microsoft; на ноутбуках бывает `Fn+F4`).'))

// m04-03: сравнение функций, столбец C, таблица «организация × статус»
ins('m04-03', 'order', p('cmp3', '**Порядок аргументов двух функций — рядом.**\n— `СУММЕСЛИ(диапазон_условия; условие; диапазон_суммы)` — одна пара «где ищем — что ищем», сумма последним.\n— `СУММЕСЛИМН(диапазон_суммы; диапазон_условия1; условие1; диапазон_условия2; условие2…)` — сумма первым, дальше пары.\n— `СЧЁТЕСЛИМН(диапазон_условия1; условие1; диапазон_условия2; условие2…)` — суммы нет, только пары.\nНа данных урока: `=СУММЕСЛИ($B$2:$B$7;"Альфа";$D$2:$D$7)` = 18 000 (все три записи Альфы), а `=СУММЕСЛИМН($D$2:$D$7;$B$2:$B$7;"Альфа";$E$2:$E$7;"Оплачено")` = 14 000 (только оплаченные).'),
  p('catC', '**Столбец C «Категория» листа «Платежи»:** P01 — Поставщик, P02 — Аренда, P03 — Аренда, P04 — Поставщик, P05 — Поставщик, P06 — Поставщик. Поэтому `=СЧЁТЕСЛИ($C$2:$C$7;"Поставщик")` = 4, а `=СУММЕСЛИ($C$2:$C$7;"Поставщик";$D$2:$D$7)` = 29 000 (12 000 + 9 000 + 6 000 + 2 000).'),
  p('cross', '**Таблица «организация × статус» одной формулой (HARD).** На новом листе «Итоги по статусам» введите: A2:A4 — Альфа, Бета, Гамма; B1 — «Оплачено», C1 — «Не оплачено». В B2:\n`=СУММЕСЛИМН(Платежи!$D$2:$D$7;Платежи!$B$2:$B$7;$A2;Платежи!$E$2:$E$7;B$1)`\nАнгл.: `=SUMIFS(Платежи!$D$2:$D$7,Платежи!$B$2:$B$7,$A2,Платежи!$E$2:$E$7,B$1)`\nПротяните вправо на C2, затем вниз до строки 4. Знак `$` перед A закрепляет столбец организаций, а `$` перед 1 в `B$1` — строку заголовков статусов. Эталон: Альфа — 14 000 и 4 000; Бета — 8 000 и 6 000; Гамма — 9 000 и 0. Сумма всех шести ячеек — 41 000.'))
addFigs('m04-03', [{ after: 'cross', caption: 'Учебная реконструкция: лист «Итоги по статусам» — результат формулы после протягивания вправо и вниз.', src: excelSheet('Итоги по статусам', [['Организация', 'Оплачено', 'Не оплачено'], ['Альфа', '14000', '4000'], ['Бета', '8000', '6000'], ['Гамма', '9000', '0']], { selected: [1, 1], formula: '=СУММЕСЛИМН(Платежи!$D$2:$D$7;Платежи!$B$2:$B$7;$A2;Платежи!$E$2:$E$7;B$1)' }) }])

// m04-04: осмысленные примеры ошибок, ЕСНД
ins('m04-04', 'iferr', p('errex', '**Примеры, где ЕСЛИОШИБКА уместна.** Пример `ЕСЛИОШИБКА(D2/E2;…)` выше показывает синтаксис, но в «Платежах» E — текстовый статус, и деление там даёт #ЗНАЧ!. Рабочие примеры:\n— #ДЕЛ/0!: средняя сумма записи по организации, которой в данных нет: `=ЕСЛИОШИБКА(СУММЕСЛИ($B$2:$B$7;"Дельта";$D$2:$D$7)/СЧЁТЕСЛИ($B$2:$B$7;"Дельта");"нет записей")` → «нет записей» (в «Дельте» ноль записей, деление на ноль).\n— #Н/Д: поиск кода, которого нет в справочнике (подробно — в следующем уроке про ВПР): `=ЕСНД(ВПР("X99";Справочник!$A$2:$B$4;2;ЛОЖЬ);"нет в справочнике")` → «нет в справочнике». Англ.: `=IFNA(VLOOKUP("X99",Справочник!$A$2:$B$4,2,FALSE),"нет в справочнике")`.\nЕСНД ловит только #Н/Д: опечатка в формуле (#ИМЯ?) останется видимой, а `ЕСЛИОШИБКА` её бы спрятала. Если имя функции в вашей версии не подсказывается, проверьте его в справке.'))

// m04-05: схема ВПР и опасный случай без ЛОЖЬ
ins('m04-05', 'args', p('map5', '**Откуда берётся число 2.** В формуле `ВПР(E2;$A$2:$C$4;2;ЛОЖЬ)` таблица — три столбца: 1 — код (A, по нему ищем), 2 — организация (B), 3 — группа (C). «2» — номер столбца внутри таблицы, считая слева с единицы, а не буква листа. Нужна группа вместо названия — пишите 3. Если вставить столбец между A и B, номер сам не изменится: проверьте формулу.'),
  p('danger5', '**Самый опасный случай: четвёртый аргумент опущен.** Формула `=ВПР("X99";$A$2:$C$4;2)` без ЛОЖЬ ищет приблизительно в отсортированном списке. Код «X99» стоит после «C03», поэтому Excel вернёт «Гамма» — не ошибку. «B05» тоже найдёт «Бета» (ближайший меньший). Без ошибки неверный ответ уйдёт в отчёт. Правило: для кодов и названий всегда `ЛОЖЬ` (или 0).'))
addFigs('m04-05', [{ after: 'map5', caption: 'Учебная схема: справочник с номерами столбцов — ВПР ищет код в столбце 1 и возвращает столбец 2 (названия в строке номеров условные).', src: excelSheet('Справочник: номера столбцов для ВПР', [['1 (ищем здесь)', '2 (вернуть)', '3'], ['Код', 'Организация', 'Группа'], ['A01', 'Альфа', 'Север'], ['B02', 'Бета', 'Юг'], ['C03', 'Гамма', 'Север']], { selected: [3, 1], formula: '=ВПР("B02";$A$2:$C$4;2;ЛОЖЬ)' }) }])

